Set tSSLConfigs = [] Try {
New $NAMESPACE Set $NAMESPACE = "%SYS"
Set tCall = "Call Security.SSLConfigs_ListNames()" Set tStatement = ##class(%SQL.Statement).%New() Set pStatus = tStatement.%Prepare(tCall) $$$ThrowOnError(pStatus) Set tResultSet = tStatement.%Execute() While tResultSet.%Next(.pStatus) { $$$ThrowOnError(pStatus)
Set tSSLConfigName = tResultSet.%Get("Name")
Set tConfigObj = {}
Set pStatus = ##class(Security.SSLConfigs).Get(tSSLConfigName,.tProperties) $$$ThrowOnError(pStatus)
Set tConfigObj.Name = tSSLConfigName Set tConfigObj.CAFile = tProperties("CAFile") Set tConfigObj.CAPath = tProperties("CAPath") Set tConfigObj.CRLFile = tProperties("CRLFile") Set tConfigObj.CertificateFile = tProperties("CertificateFile") Set tConfigObj.CipherList = tProperties("CipherList") Set tConfigObj.Description = tProperties("Description") Set tConfigObj.Enabled = tProperties("Enabled") Set tConfigObj.PrivateKeyFile = tProperties("PrivateKeyFile") Set tConfigObj.PrivateKeyPassword = tProperties("PrivateKeyPassword") Set tConfigObj.PrivateKeyType = tProperties("PrivateKeyType") Set tConfigObj.Protocols = tProperties("Protocols") Set tConfigObj.Type = tProperties("Type") Set tConfigObj.VerifyDepth = tProperties("VerifyDepth") Set tConfigObj.VerifyPeer = tProperties("VerifyPeer")
Do tSSLConfigs.%Push(tConfigObj)
} $$$ThrowOnError(pStatus) } Catch eException { Set pStatus = eException.AsStatus() } Quit tSSLConfigs

	
